Hiya,


I'm running into an issue that I think isn't really something you can fix directly, but was wondering if you might have some out of the box ideas to solve it. The TL;DR is:

- I'm downloading the Fedora CoreOS image using proxmox_virtual_environment_download_file.
- They only offer .qcow2.xz compressed images
- I need to set content type to ISO as thats the only one that supports the "decompression_algorithm" parameter.
- Importing from this image fails with `│ #1: received an HTTP 400 response - Reason: Parameter verification failed. (virtio0: local:iso/fedora-coreos-43.20251120.3.0.img has wrong type 'iso' - needs to be 'images' or 'import')`

If at all possible I'd like to avoid using the regular proxmox_virtual_environment_file and local_exec like shenanigans. For reference this is the full TF i'm using:

```hcl

data "http" "fcos_stable" {
  url = "https://builds.coreos.fedoraproject.org/streams/stable.json"
}

locals {
  fcos_pve     = jsondecode(data.http.fcos_stable.response_body).architectures.x86_64.artifacts.proxmoxve
  fcos_latest  = local.fcos_pve.formats["qcow2.xz"].disk.location
  fcos_sha256  = local.fcos_pve.formats["qcow2.xz"].disk.sha256
  fcos_release = local.fcos_pve.release

  systemd_units = [
    for filename in fileset("${path.module}", "systemd_units/*.service") : {
      enabled  = true
      name     = basename(filename)
      contents = file(filename)
    }
  ]
}

resource "proxmox_virtual_environment_download_file" "latest_fcos" {
  content_type            = "iso"
  datastore_id            = var.datastore_iso
  file_name               = "fedora-coreos-${local.fcos_release}.img"
  node_name               = data.proxmox_virtual_environment_nodes.available_nodes.names[0]
  url                     = local.fcos_latest
  decompression_algorithm = "zst"
  checksum                = local.fcos_sha256
  checksum_algorithm      = "sha256"
}

resource "proxmox_virtual_environment_file" "coreos_ignition" {
  content_type = "snippets"
  datastore_id = var.datastore_snippets
  node_name    = data.proxmox_virtual_environment_nodes.available_nodes.names[0]

  source_raw {
    file_name = "coreos_template.ign"
    data = jsonencode({
      ignition = {
        version = "3.5.0"
      }

      passwd = {
        users = [{
          name              = "core"
          groups            = ["docker"]
          sshAuthorizedKeys = ["ssh-ed25519 <ssh key here>"]
        }]
      }

      systemd = {
        units = local.systemd_units
      }
    })
  }
}

resource "proxmox_virtual_environment_vm" "coreos_template" {
  name      = "fedora-coreos-test-tf"
  bios      = "ovmf"
  machine   = "q35"
  vm_id     = 30000
  node_name = data.proxmox_virtual_environment_nodes.available_nodes.names[0]
  on_boot   = true
  tags      = [local.fcos_release]
  template  = true

  cpu {
    cores = 4
    numa  = false
    type  = "host"
  }

  memory {
    dedicated = 4096
  }

  agent {
    enabled = true
    trim    = true
  }

  disk {
    datastore_id = var.datastore_vm
    import_from  = proxmox_virtual_environment_download_file.latest_fcos.id
    interface    = "virtio0"
    size         = 10
  }

  efi_disk {
    datastore_id      = var.datastore_vm
    file_format       = "raw"
    pre_enrolled_keys = true
    type              = "4m"
  }

  initialization {
    datastore_id = var.datastore_vm
    interface    = "ide2"

    ip_config {
      ipv4 {
        address = "dhcp"
      }
    }
    vendor_data_file_id = proxmox_virtual_environment_file.coreos_ignition.id
  }

  operating_system {
    type = "l26"
  }

  network_device {
    bridge = proxmox_virtual_environment_network_linux_bridge.vmbr0.name
    mtu    = proxmox_virtual_environment_network_linux_bridge.vmbr0.mtu
  }
}
```
